    {
        var (db, _, clock, bus, service) = CreateSut("alice", Roles.Customer);
        var accountId = TestKit.Account(db, "alice", 500m);

        var card = await service.IssueAsync(accountId);

        var saved = db.Cards.Single(c => c.Id == card.Id);
